-- ============================================================
-- 032_nordic_personas.sql
-- 100 Nordic personas: Swedish (majority), Finnish, Norwegian,
-- Danish, and Icelandic personalities.
-- UUIDs: 25e – 2c1
-- ============================================================

INSERT INTO public.personas (id, name, bio, birth_year, death_year) VALUES
  -- ── Swedish historical ──────────────────────────────────────
  ('a0000000-0000-0000-0000-00000000025e', 'Gustav Vasa', 'Swedish nobleman who led a successful rebellion against Danish rule, became King of Sweden in 1523, founded the Vasa dynasty, and established Lutheranism as the state religion — widely regarded as the father of modern Sweden.', 1496, 1560),
  ('a0000000-0000-0000-0000-00000000025f', 'Gustavus Adolphus', 'King of Sweden 1611–1632, considered one of the greatest military commanders in history; transformed Sweden into a major European power during the Thirty Years'' War before dying at the Battle of Lützen.', 1594, 1632),
  ('a0000000-0000-0000-0000-000000000260', 'Queen Christina of Sweden', 'Daughter of Gustavus Adolphus who became Queen of Sweden at age six; one of the most educated rulers of her era, she stunned Europe by abdicating the throne in 1654 and converting to Catholicism.', 1626, 1689),
  ('a0000000-0000-0000-0000-000000000261', 'Charles XII of Sweden', 'King of Sweden 1697–1718 and last great warrior king of the Swedish Empire; won spectacular early victories in the Great Northern War before a catastrophic defeat at Poltava in 1709 ended Swedish superpower status.', 1682, 1718),
  ('a0000000-0000-0000-0000-000000000262', 'Carl Linnaeus', 'Swedish botanist and physician who formalized the system of naming organisms, known as binomial nomenclature; his Systema Naturae laid the groundwork for modern taxonomy and earned him the title "Prince of Botanists".', 1707, 1778),
  ('a0000000-0000-0000-0000-000000000263', 'Anders Celsius', 'Swedish astronomer and professor at Uppsala University who in 1742 proposed the centigrade temperature scale — later named Celsius in his honour — and made important observations on the aurora borealis.', 1701, 1744),
  ('a0000000-0000-0000-0000-000000000264', 'Emanuel Swedenborg', 'Swedish scientist, inventor, and mystic who made contributions to mathematics, metallurgy, and anatomy before experiencing religious visions in 1744; his theological writings founded the New Church movement.', 1688, 1772),
  ('a0000000-0000-0000-0000-000000000265', 'Alfred Nobel', 'Swedish chemist and engineer who invented dynamite in 1867 and held over 350 patents; troubled by his legacy of destruction, he bequeathed his fortune to establish the Nobel Prizes, awarded annually since 1901.', 1833, 1896),
  ('a0000000-0000-0000-0000-000000000266', 'August Strindberg', 'Swedish playwright and novelist considered the father of modern Swedish literature; works including Miss Julie and The Father pioneered naturalism and expressionism and profoundly influenced 20th-century theatre.', 1849, 1912),
  ('a0000000-0000-0000-0000-000000000267', 'Selma Lagerlöf', 'Swedish author who in 1909 became the first woman to win the Nobel Prize in Literature; her works including Gösta Berlings Saga and The Wonderful Adventures of Nils draw richly on Swedish legend and landscape.', 1858, 1940),
  ('a0000000-0000-0000-0000-000000000268', 'Jenny Lind', 'Swedish soprano known as "The Swedish Nightingale" whose extraordinary voice and charitable character made her the most celebrated singer of the 19th century; her 1850 American tour managed by P.T. Barnum was a sensation.', 1820, 1887),
  ('a0000000-0000-0000-0000-000000000269', 'Hjalmar Branting', 'Swedish politician who co-founded the Social Democratic Party in 1889 and served as Prime Minister three times; his work to establish parliamentary democracy and workers'' rights earned him the Nobel Peace Prize in 1921.', 1860, 1925),
  ('a0000000-0000-0000-0000-00000000026a', 'Axel Oxenstierna', 'Swedish statesman who served as Lord High Chancellor for over 40 years under three monarchs; effectively governed Sweden during the Thirty Years'' War and the regency of Queen Christina, shaping Sweden into a great power.', 1583, 1654),
  ('a0000000-0000-0000-0000-00000000026b', 'Raoul Wallenberg', 'Swedish diplomat and businessman who in 1944 was sent to Nazi-occupied Budapest and saved tens of thousands of Hungarian Jews by issuing protective passports; arrested by Soviet forces in 1945 and died in captivity.', 1912, 1947),
  ('a0000000-0000-0000-0000-00000000026c', 'Dag Hammarskjöld', 'Swedish economist and diplomat who served as UN Secretary-General 1953–1961; considered one of the greatest holders of the office, he died in a plane crash during the Congo Crisis and was posthumously awarded the Nobel Peace Prize.', 1905, 1961),
  -- ── Swedish 20th century ────────────────────────────────────
  ('a0000000-0000-0000-0000-00000000026d', 'Olof Palme', 'Swedish Social Democratic politician who served as Prime Minister 1969–1976 and 1982–1986; a prominent voice of the international left and fierce critic of the Vietnam War, he was assassinated in Stockholm on 28 February 1986 in an unsolved case.', 1927, 1986),
  ('a0000000-0000-0000-0000-00000000026e', 'Ingmar Bergman', 'Swedish film and theatre director widely regarded as one of the greatest filmmakers of all time; works including The Seventh Seal, Wild Strawberries, and Fanny and Alexander explore existential themes of mortality, faith, and human relationships.', 1918, 2007),
  ('a0000000-0000-0000-0000-00000000026f', 'Greta Garbo', 'Swedish-American actress who became one of Hollywood''s biggest stars in the 1930s with films including Grand Hotel and Ninotchka; famously reclusive, she retired at 35 and lived out her life in near-total seclusion in New York.', 1905, 1990),
  ('a0000000-0000-0000-0000-000000000270', 'Ingrid Bergman', 'Swedish-American actress who won three Academy Awards for Gaslight, Anastasia, and Murder on the Orient Express; Casablanca remains her most iconic film; her affair with director Roberto Rossellini caused a major Hollywood scandal.', 1915, 1982),
  ('a0000000-0000-0000-0000-000000000271', 'Astrid Lindgren', 'Swedish author who created Pippi Longstocking, Emil of Lönneberga, and Ronja Rövardotter; one of the best-selling fiction authors of all time, she profoundly shaped Swedish childhood culture and children''s literature worldwide.', 1907, 2002),
  -- ── Swedish contemporary ────────────────────────────────────
  ('a0000000-0000-0000-0000-000000000272', 'Björn Borg', 'Swedish tennis legend who won 11 Grand Slam titles including five consecutive Wimbledon championships 1976–1980; retired at only 26, he later founded a successful fashion label and remains an icon of 1970s sport.', 1956, null),
  ('a0000000-0000-0000-0000-000000000273', 'Zlatan Ibrahimović', 'Swedish footballer widely considered the greatest to ever play for Sweden; had a career spanning Ajax, Juventus, Inter Milan, Barcelona, AC Milan, PSG, Manchester United, and LA Galaxy before retiring from international football in 2023.', 1981, null),
  ('a0000000-0000-0000-0000-000000000274', 'Greta Thunberg', 'Swedish climate activist who in August 2018 began a school strike outside the Swedish parliament that sparked a global youth climate movement; addressed world leaders at COP24 and the UN, and was named Time Person of the Year 2019.', 2003, null),
  ('a0000000-0000-0000-0000-000000000275', 'Avicii', 'Swedish DJ and record producer born Tim Bergling whose track Levels became one of the defining anthems of the EDM era; breakthrough hit Wake Me Up reached #1 in 22 countries; struggled with health issues and died in Muscat, Oman in 2018, aged 28.', 1989, 2018),
  ('a0000000-0000-0000-0000-000000000276', 'Stieg Larsson', 'Swedish journalist and author who spent decades fighting far-right extremism as editor of Expo magazine; his posthumously published Millennium trilogy — beginning with The Girl with the Dragon Tattoo — became a global publishing phenomenon.', 1954, 2004),
  ('a0000000-0000-0000-0000-000000000277', 'Henning Mankell', 'Swedish crime author best known for his Kurt Wallander detective series set in the fictional Ystad; split his time between Sweden and Mozambique and was a committed activist; diagnosed with cancer, he died in Gothenburg in 2015.', 1948, 2015),
  ('a0000000-0000-0000-0000-000000000278', 'Agnetha Fältskog', 'Swedish singer and one quarter of ABBA; her crystalline soprano voice and songwriting contributions defined the group''s sound; had a successful solo career before withdrawing from public life for many years.', 1950, null),
  ('a0000000-0000-0000-0000-000000000279', 'Björn Ulvaeus', 'Swedish singer-songwriter and one quarter of ABBA; with Benny Andersson wrote the music and lyrics for virtually all ABBA recordings; co-created the musical Mamma Mia! which became one of the longest-running shows in history.', 1945, null),
  ('a0000000-0000-0000-0000-00000000027a', 'Benny Andersson', 'Swedish musician, composer, and one quarter of ABBA; a classically self-taught pianist whose melodic gift drove ABBA''s sound; post-ABBA composed the musicals Chess and Kristina från Duvemåla and leads the Benny Anderssons Orkester.', 1946, null),
  ('a0000000-0000-0000-0000-00000000027b', 'Anni-Frid Lyngstad', 'Norwegian-Swedish singer and one quarter of ABBA; born in Norway but raised in Sweden, her mezzo-soprano voice provided the earthy counterpart to Agnetha''s soprano; later married Prince Heinrich Ruzzo of Reuss and became a German princess.', 1945, null),
  ('a0000000-0000-0000-0000-00000000027c', 'Gunnar Myrdal', 'Swedish economist and sociologist who won the Nobel Prize in Economics in 1974; his landmark study An American Dilemma was a foundational work on racial inequality in the United States; husband of Alva Myrdal.', 1898, 1987),
  ('a0000000-0000-0000-0000-00000000027d', 'Alva Myrdal', 'Swedish sociologist, diplomat, and politician who won the Nobel Peace Prize in 1982 for her work on nuclear disarmament; co-wrote Nation and Family with Gunnar Myrdal, shaping Swedish welfare state policy; wife of Gunnar Myrdal.', 1902, 1986),
  ('a0000000-0000-0000-0000-00000000027e', 'Birgit Nilsson', 'Swedish dramatic soprano considered the greatest Wagnerian singer of the 20th century; her fearsome vocal power and stamina made her reign at the Metropolitan Opera and Bayreuth for over three decades.', 1918, 2005),
  ('a0000000-0000-0000-0000-00000000027f', 'Tomas Tranströmer', 'Swedish poet awarded the Nobel Prize in Literature in 2011; his sparse, imagistic poetry explores the boundaries between the conscious and unconscious and has been translated into over 60 languages; suffered a stroke in 1990 that left him partially paralysed.', 1931, 2015),
  ('a0000000-0000-0000-0000-000000000280', 'Ingemar Stenmark', 'Swedish alpine ski racer who won 86 World Cup races — a record that stood for decades — and two Olympic gold medals at the 1980 Lake Placid Games; widely regarded as the greatest slalom and giant slalom skier of all time.', 1956, null),
  ('a0000000-0000-0000-0000-000000000281', 'Max Martin', 'Swedish music producer and songwriter born Martin Karl Sandberg who has written or co-written more number-one hits than any producer in history, including songs for Britney Spears, Katy Perry, Taylor Swift, The Weeknd, and Ariana Grande.', 1971, null),
  ('a0000000-0000-0000-0000-000000000282', 'Anna Lindh', 'Swedish Social Democratic politician who served as Foreign Minister and was widely expected to become Prime Minister; a committed multilateralist and advocate for the euro, she was stabbed in a Stockholm department store in 2003 and died the following day.', 1957, 2003),
  ('a0000000-0000-0000-0000-000000000283', 'Carl Bildt', 'Swedish conservative politician who served as Prime Minister 1991–1994, negotiating Sweden''s EU entry; later served as High Representative for Bosnia, UN Envoy, and Foreign Minister 2006–2014; a prominent voice in European foreign policy.', 1949, null),
  ('a0000000-0000-0000-0000-000000000284', 'Ingvar Kamprad', 'Swedish entrepreneur who founded IKEA in 1943 at the age of 17; grew it into the world''s largest furniture retailer with stores in over 60 countries; known for his extreme frugality and unconventional business philosophy set out in The IKEA Way.', 1926, 2018),
  ('a0000000-0000-0000-0000-000000000285', 'Tage Erlander', 'Swedish Social Democratic politician who served as Prime Minister for 23 years from 1946 to 1969 — the longest of any democratically elected leader in the world; architect of the modern Swedish welfare state.', 1901, 1985),
  ('a0000000-0000-0000-0000-000000000286', 'Per Albin Hansson', 'Swedish Social Democratic politician and Prime Minister 1932–1946 who coined the concept of "Folkhemmet" (the People''s Home) — the ideological foundation of the Swedish welfare state; steered Sweden through World War II maintaining neutrality.', 1885, 1946),
  ('a0000000-0000-0000-0000-000000000287', 'King Carl XVI Gustaf', 'King of Sweden since 1973 and the longest-reigning Swedish monarch; married German noblewoman Silvia Sommerlath in 1976; under his reign the constitution was reformed to give the monarch a purely ceremonial role.', 1946, null),
  ('a0000000-0000-0000-0000-000000000288', 'Pär Lagerkvist', 'Swedish author and Nobel laureate in Literature 1951; his works — including Barabbas and The Dwarf — explore the conflict between good and evil and the search for spiritual meaning in a secular age.', 1891, 1974),
  ('a0000000-0000-0000-0000-000000000289', 'Vilhelm Moberg', 'Swedish author best known for The Emigrants tetralogy chronicling the lives of 19th-century Swedish emigrants to Minnesota; also a journalist and playwright, he was one of the most widely read Swedish authors of the 20th century.', 1898, 1973),
  ('a0000000-0000-0000-0000-00000000028a', 'Robyn', 'Swedish singer and songwriter born Robin Miriam Carlsson who broke through with the pop hit Show Me Love in 1997 and reinvented herself as an independent artist with her 2005 comeback; her album Body Talk cemented her status as a pop icon.', 1979, null),
  -- ── Finnish ─────────────────────────────────────────────────
  ('a0000000-0000-0000-0000-00000000028b', 'Carl Gustaf Emil Mannerheim', 'Finnish military commander and statesman who led Finnish forces to victory in the Finnish Civil War and the Winter War against the Soviet Union; served as Regent 1918–1919 and President of Finland 1944–1946; the defining figure of modern Finnish history.', 1867, 1951),
  ('a0000000-0000-0000-0000-00000000028c', 'Jean Sibelius', 'Finnish composer whose works — including Finlandia, the Violin Concerto, and seven symphonies — forged a national musical identity for Finland; the most important composer of the late Romantic era outside Central Europe, revered as a Finnish national hero.', 1865, 1957),
  ('a0000000-0000-0000-0000-00000000028d', 'Alvar Aalto', 'Finnish architect and designer considered one of the greats of 20th-century modernism; pioneered the use of organic forms and natural materials, designing iconic buildings including the Paimio Sanatorium, Finlandia Hall, and MIT''s Baker House.', 1898, 1976),
  ('a0000000-0000-0000-0000-00000000028e', 'Urho Kekkonen', 'Finnish Centre Party politician who served as President of Finland for 26 years from 1956 to 1982 — the longest presidential tenure in Finnish history; master of Finlandisation policy, maintaining sovereignty through careful neutrality between East and West.', 1900, 1986),
  ('a0000000-0000-0000-0000-00000000028f', 'Paavo Nurmi', 'Finnish long-distance runner known as "The Flying Finn" who won nine Olympic gold medals at the 1920, 1924, and 1928 Games; set 22 official world records and dominated middle- and long-distance running throughout the 1920s.', 1897, 1973),
  ('a0000000-0000-0000-0000-000000000290', 'Tove Jansson', 'Finnish author and artist who created the Moomin characters, a family of round white hippopotamus-like creatures whose adventures have been translated into over 50 languages and adapted into films and television worldwide.', 1914, 2001),
  ('a0000000-0000-0000-0000-000000000291', 'Linus Torvalds', 'Finnish-American software engineer who created the Linux kernel in 1991 as a student at the University of Helsinki; Linux now powers the majority of the world''s servers, supercomputers, Android phones, and the International Space Station.', 1969, null),
  ('a0000000-0000-0000-0000-000000000292', 'Mika Häkkinen', 'Finnish racing driver who won back-to-back Formula One World Championships with McLaren in 1998 and 1999; known as "The Flying Finn", his fierce rivalry with Michael Schumacher is considered one of the greatest in F1 history.', 1968, null),
  ('a0000000-0000-0000-0000-000000000293', 'Kimi Räikkönen', 'Finnish Formula One driver who won the World Championship with Ferrari in 2007; known as "The Iceman" for his famously taciturn personality, he made a remarkable comeback with Lotus before retiring in 2021 having competed in a record 349 Grands Prix.', 1979, null),
  ('a0000000-0000-0000-0000-000000000294', 'Martti Ahtisaari', 'Finnish diplomat and politician who served as President of Finland 1994–2000 and spent decades mediating international conflicts including Namibia, Kosovo, and Aceh; awarded the Nobel Peace Prize in 2008 for his peace-building work.', 1937, 2023),
  ('a0000000-0000-0000-0000-000000000295', 'Sanna Marin', 'Finnish Social Democratic politician who became Prime Minister of Finland in 2019 at age 34, making her the world''s youngest sitting head of government at the time; led Finland through the COVID-19 pandemic and the decision to apply for NATO membership in 2022.', 1985, null),
  ('a0000000-0000-0000-0000-000000000296', 'Tarja Halonen', 'Finnish Social Democratic politician who served as President of Finland 2000–2012, the first woman to hold the office; also served as Foreign Minister and is known for her strong advocacy for human rights and Nordic cooperation.', 1943, null),
  ('a0000000-0000-0000-0000-000000000297', 'Alexander Stubb', 'Finnish politician who served as Prime Minister 2014–2015, Finance Minister, and became President of Finland in 2024; an avid triathlete and enthusiastic communicator, he is one of Europe''s most internationally recognised Finnish politicians.', 1968, null),
  ('a0000000-0000-0000-0000-000000000298', 'Juho Kusti Paasikivi', 'Finnish statesman who served as President of Finland 1946–1956; architect of the Paasikivi–Kekkonen line of cautious but sovereign coexistence with the Soviet Union; previously served as Prime Minister twice and was instrumental in armistice negotiations.', 1870, 1956),
  ('a0000000-0000-0000-0000-000000000299', 'Mauno Koivisto', 'Finnish Social Democratic politician who served as Prime Minister twice and as President of Finland 1982–1994; under his presidency Finland expanded its role in European affairs, culminating in the application to join the EU.', 1923, 2017),
  -- ── Norwegian ────────────────────────────────────────────────
  ('a0000000-0000-0000-0000-00000000029a', 'Henrik Ibsen', 'Norwegian playwright considered the father of modern drama; works including A Doll''s House, Hedda Gabler, and Ghosts broke with theatrical convention to explore psychological realism and social issues, influencing virtually every playwright who followed.', 1828, 1906),
  ('a0000000-0000-0000-0000-00000000029b', 'Edvard Grieg', 'Norwegian Romantic composer whose Piano Concerto in A minor and Peer Gynt suites brought Norwegian folk music to international audiences; the defining voice of Norwegian national Romanticism and one of the most celebrated composers of his era.', 1843, 1907),
  ('a0000000-0000-0000-0000-00000000029c', 'Edvard Munch', 'Norwegian painter whose intensely emotional works pioneered expressionism; The Scream — depicting a figure overwhelmed by existential anxiety — is one of the most recognised paintings in the world; his work profoundly influenced 20th-century art.', 1863, 1944),
  ('a0000000-0000-0000-0000-00000000029d', 'Fridtjof Nansen', 'Norwegian explorer, scientist, and diplomat who led the first crossing of Greenland on skis in 1888 and came within 4 degrees of the North Pole in 1895; awarded the Nobel Peace Prize in 1922 for his humanitarian work with refugees.', 1861, 1930),
  ('a0000000-0000-0000-0000-00000000029e', 'Roald Amundsen', 'Norwegian explorer who in 1911 led the first expedition to reach the South Pole, beating Robert Falcon Scott by 33 days; also the first to navigate the Northwest Passage and the first person undisputedly to reach both poles.', 1872, 1928),
  ('a0000000-0000-0000-0000-00000000029f', 'Thor Heyerdahl', 'Norwegian adventurer and ethnographer who in 1947 sailed the balsa raft Kon-Tiki from Peru to Polynesia to demonstrate that pre-Columbian South Americans could have settled Polynesia; later led Ra expeditions across the Atlantic on papyrus boats.', 1914, 2002),
  ('a0000000-0000-0000-0000-0000000002a0', 'Knut Hamsun', 'Norwegian author awarded the Nobel Prize in Literature in 1920 for Hunger; his novels pioneered stream-of-consciousness narrative technique and influenced Kafka, Hemingway, and many others; his reputation is permanently tainted by his collaboration with the Nazis.', 1859, 1952),
  ('a0000000-0000-0000-0000-0000000002a1', 'Sigrid Undset', 'Norwegian author who won the Nobel Prize in Literature in 1928; her medieval trilogy Kristin Lavransdatter is considered a masterpiece of historical fiction; she converted to Catholicism in 1924 and fled Norway after the German invasion in 1940.', 1882, 1949),
  ('a0000000-0000-0000-0000-0000000002a2', 'Magnus Carlsen', 'Norwegian chess grandmaster who became World Chess Champion in 2013 and held the title until 2023; widely regarded as the greatest chess player of all time, he achieved the highest FIDE rating in history and dominated the game across all formats.', 1990, null),
  ('a0000000-0000-0000-0000-0000000002a3', 'Sonja Henie', 'Norwegian figure skater who won three Olympic gold medals in 1928, 1932, and 1936, and ten consecutive world championships; turned professional and became one of the highest-paid actresses in Hollywood, revolutionising both sport and entertainment.', 1912, 1969),
  ('a0000000-0000-0000-0000-0000000002a4', 'Jens Stoltenberg', 'Norwegian Labour politician who served as Prime Minister of Norway 2000–2001 and 2005–2013; served as NATO Secretary General 2014–2024, overseeing the Alliance through the Russia–Ukraine war and a historic expansion of membership.', 1959, null),
  ('a0000000-0000-0000-0000-0000000002a5', 'Erna Solberg', 'Norwegian Conservative politician who served as Prime Minister of Norway 2013–2021, the second woman to hold the office; known for immigration reform, digitisation, and a pragmatic centre-right leadership style nicknamed "Iron Erna".', 1961, null),
  ('a0000000-0000-0000-0000-0000000002a6', 'Gro Harlem Brundtland', 'Norwegian Labour politician who served as Prime Minister three times and was the first woman to hold the office in Norway; chaired the UN World Commission on Environment and Development, producing the landmark Brundtland Report on sustainable development in 1987.', 1939, null),
  ('a0000000-0000-0000-0000-0000000002a7', 'Roald Dahl', 'British-Norwegian author of Norwegian heritage who wrote some of the best-loved children''s books of the 20th century, including Charlie and the Chocolate Factory, Matilda, and The BFG; also wrote macabre adult short stories and served as an RAF ace pilot.', 1916, 1990),
  ('a0000000-0000-0000-0000-0000000002a8', 'King Harald V', 'King of Norway since 1991; married commoner Sonja Haraldsen in 1968 despite initial opposition — a turning point for the Norwegian monarchy; known for his sailing achievements, having competed in three Olympics.', 1937, null),
  -- ── Danish ───────────────────────────────────────────────────
  ('a0000000-0000-0000-0000-0000000002a9', 'Hans Christian Andersen', 'Danish author whose fairy tales — including The Little Mermaid, The Ugly Duckling, Thumbelina, and The Snow Queen — have been translated into more languages than any book except the Bible; born in poverty, he became one of the most beloved writers in history.', 1805, 1875),
  ('a0000000-0000-0000-0000-0000000002aa', 'Søren Kierkegaard', 'Danish philosopher and theologian considered the first existentialist philosopher; his works — written often under pseudonyms — explored anxiety, despair, and the nature of faith, profoundly influencing Heidegger, Sartre, and 20th-century theology.', 1813, 1855),
  ('a0000000-0000-0000-0000-0000000002ab', 'Niels Bohr', 'Danish physicist who developed the Bohr model of the atom in 1913 and made foundational contributions to quantum mechanics; awarded the Nobel Prize in Physics in 1922; helped escape Nazi-occupied Denmark in 1943 and contributed to the Manhattan Project.', 1885, 1962),
  ('a0000000-0000-0000-0000-0000000002ac', 'Karen Blixen', 'Danish author who wrote under the pen name Isak Dinesen; Out of Africa chronicles her years running a coffee plantation in Kenya; her Seven Gothic Tales established her as a master of the short-story form; nominated for the Nobel Prize multiple times.', 1885, 1962),
  ('a0000000-0000-0000-0000-0000000002ad', 'Tycho Brahe', 'Danish astronomer who made the most precise observations of stellar and planetary positions in the pre-telescope era; his data was used by Johannes Kepler to derive the laws of planetary motion; lost part of his nose in a duel and wore a prosthetic.', 1546, 1601),
  ('a0000000-0000-0000-0000-0000000002ae', 'Lars von Trier', 'Danish film director and co-founder of the Dogme 95 movement; his provocative films — including Breaking the Waves, Dancer in the Dark, Melancholia, and The House That Jack Built — have divided critics and won major awards at Cannes.', 1956, null),
  ('a0000000-0000-0000-0000-0000000002af', 'Mette Frederiksen', 'Danish Social Democratic politician who became Prime Minister of Denmark in 2019 at age 41; navigated Denmark through the COVID-19 pandemic and led a centre-left government with firm immigration policies unusual for the European left.', 1977, null),
  ('a0000000-0000-0000-0000-0000000002b0', 'Queen Margrethe II', 'Queen of Denmark 1972–2024 and the first Danish female monarch since the 14th century; an accomplished artist, translator, and archaeologist, she abdicated on 14 January 2024 — New Year''s Day — handing power to her son Frederik X.', 1940, null),
  ('a0000000-0000-0000-0000-0000000002b1', 'Ole Rømer', 'Danish astronomer who in 1676 made the first quantitative measurements of the speed of light by observing variations in the timing of Jupiter''s moon Io; also invented the Rømer temperature scale and reformed the Danish calendar.', 1644, 1710),
  ('a0000000-0000-0000-0000-0000000002b2', 'Victor Borge', 'Danish-American comedian, conductor, and pianist known as "The Clown Prince of Denmark"; his blend of classical music and slapstick comedy made him one of the most beloved entertainers of the 20th century; his Broadway show Comedy in Music ran for 849 performances.', 1909, 2000),
  ('a0000000-0000-0000-0000-0000000002b3', 'Viggo Mortensen', 'Danish-American actor, poet, and artist who gained worldwide fame as Aragorn in Peter Jackson''s Lord of the Rings trilogy; has since pursued artistically challenging roles in films including Eastern Promises, A History of Violence, and Green Book.', 1958, null),
  ('a0000000-0000-0000-0000-0000000002b4', 'King Frederik X', 'King of Denmark since 14 January 2024 following the abdication of his mother Queen Margrethe II; a former naval officer and keen athlete who competed in the 1996 Atlanta Olympics; married Australian Mary Donaldson in 2004.', 1968, null),
  -- ── Icelandic ────────────────────────────────────────────────
  ('a0000000-0000-0000-0000-0000000002b5', 'Björk', 'Icelandic singer, composer, and actress who first gained attention with the alternative band The Sugarcubes before releasing Debut in 1993; her boundary-defying albums and performances blend pop, electronica, classical music, and avant-garde art.', 1965, null),
  ('a0000000-0000-0000-0000-0000000002b6', 'Halldór Laxness', 'Icelandic novelist who won the Nobel Prize in Literature in 1955; his works — including Independent People and The Atom Station — portray Icelandic life and society with epic scope and dark irony; the most celebrated Icelandic author of the 20th century.', 1902, 1998),
  ('a0000000-0000-0000-0000-0000000002b7', 'Vigdís Finnbogadóttir', 'Icelandic politician who served as President of Iceland 1980–1996, making her the world''s first democratically elected female president; a former theatre director and French teacher, she championed Icelandic language and culture throughout her presidency.', 1930, null),
  ('a0000000-0000-0000-0000-0000000002b8', 'Leif Erikson', 'Norse explorer from Iceland who around the year 1000 became the first known European to set foot on mainland North America — nearly 500 years before Columbus; established a settlement at Vinland, believed to be in Newfoundland.', 970, 1020),
  ('a0000000-0000-0000-0000-0000000002b9', 'Jón Sigurðsson', 'Icelandic statesman and scholar who led the campaign for Icelandic home rule from Denmark in the 19th century; his persistence secured the restoration of the Althing in 1845 and increasing Icelandic autonomy; revered as the father of Icelandic independence, born on Iceland''s national day 17 June.', 1811, 1879),
  -- ── More Swedish and Nordic ──────────────────────────────────
  ('a0000000-0000-0000-0000-0000000002ba', 'Anders Zorn', 'Swedish painter, etcher, and sculptor considered the greatest Swedish artist of his era; renowned for his virtuoso technique in depicting water and female figures, he was celebrated across Europe and America and painted three US presidents.', 1860, 1920),
  ('a0000000-0000-0000-0000-0000000002bb', 'Carl Larsson', 'Swedish painter whose warm watercolour depictions of family life at his home Lilla Hyttnäs in Sundborn defined an idealised image of Swedish domesticity that influenced Scandinavian design and interior aesthetics worldwide.', 1853, 1919),
  ('a0000000-0000-0000-0000-0000000002bc', 'Evert Taube', 'Swedish troubadour, artist, and author whose romantic ballads set in Italy and Argentina became beloved standards of Swedish song; often called the greatest Swedish songwriter and singer of the 20th century.', 1890, 1976),
  ('a0000000-0000-0000-0000-0000000002bd', 'Ivar Kreuger', 'Swedish entrepreneur and financier known as "The Match King" who built a global match monopoly spanning dozens of countries in the 1920s; his empire collapsed in the Great Depression revealing massive fraud; he died by suicide in Paris in 1932.', 1880, 1932),
  ('a0000000-0000-0000-0000-0000000002be', 'Anita Ekberg', 'Swedish actress best known for her iconic scene in the Trevi Fountain in Federico Fellini''s La Dolce Vita (1960); a striking blonde beauty who became a symbol of 1950s Hollywood glamour and Italian cinema.', 1931, 2015),
  ('a0000000-0000-0000-0000-0000000002bf', 'Fredrika Bremer', 'Swedish novelist and feminist pioneer whose writings advocated for women''s education, professional rights, and independence; her 1856 novel Hertha sparked public debate leading to legislative reforms granting women greater legal status in Sweden.', 1801, 1865),
  ('a0000000-0000-0000-0000-0000000002c0', 'Poul Schlüter', 'Danish Conservative politician who served as Prime Minister of Denmark 1982–1993, the first Conservative prime minister since 1901; led centre-right coalition governments through economic reform and European integration; resigned after the Tamilgate refugee scandal.', 1929, 2021),
  ('a0000000-0000-0000-0000-0000000002c1', 'King Gustaf V', 'King of Sweden 1907–1950 who reigned through both World Wars maintaining Swedish neutrality; an avid tennis player known on the courts as "Mr G"; his long reign of 43 years saw Sweden modernise into a mature parliamentary democracy.', 1858, 1950);
